<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__,2).'/config/config.php';
function director_dashboard_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())director_dashboard_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))director_dashboard_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);if(!in_array(($_SESSION['role']??''),['director','sub_director','headteacher'],true))director_dashboard_json(403,['ok'=>false,'message'=>'This dashboard is for school leadership accounts.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);if(!$school)director_dashboard_json(422,['ok'=>false,'message'=>'Choose a school.']);
try{$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())director_dashboard_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$q=$db->prepare("SELECT COUNT(*) pupils,SUM(created_at>=DATE_SUB(CURRENT_DATE,INTERVAL 30 DAY)) new_pupils FROM pupils WHERE school_id=? AND status='active'");$q->execute([$school]);$pupils=$q->fetch()?:['pupils'=>0,'new_pupils'=>0];$roles="'director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'";$q=$db->prepare("SELECT COUNT(DISTINCT u.id) FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=? AND u.status='active' AND u.role IN ($roles)");$q->execute([$school]);$staff=(int)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) marked,SUM(a.attendance_status IN ('present','late')) attended,SUM(a.attendance_status='excused') excused FROM pupil_attendance a WHERE a.school_id=? AND a.attendance_date>=DATE_SUB(CURRENT_DATE,INTERVAL 6 DAY) AND a.attendance_date<=CURRENT_DATE");$q->execute([$school]);$attendance=$q->fetch()?:['marked'=>0,'attended'=>0,'excused'=>0];$marked=(int)$attendance['marked'];$eligible=$marked-(int)$attendance['excused'];$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type='payment' THEN amount WHEN entry_type='payment_reversal' THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND created_at>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')");$q->execute([$school]);$payments=(float)$q->fetchColumn();$q=$db->prepare("SELECT COALESCE(SUM(balance),0) FROM (SELECT pupil_id,SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END) balance FROM school_fee_ledger WHERE school_id=? GROUP BY pupil_id HAVING balance>0) b");$q->execute([$school]);$arrears=(float)$q->fetchColumn();$q=$db->prepare('SELECT COUNT(*) FROM teaching_records WHERE school_id=? AND taught_on>=DATE_SUB(CURRENT_DATE,INTERVAL 29 DAY)');$q->execute([$school]);$confirmed=(int)$q->fetchColumn();$pending=0;foreach([['schemes_of_work','submitted'],['lesson_plans','submitted'],['teacher_reports','submitted'],['school_exams','submitted'],['staff_leave_requests','pending'],['inventory_requests','pending']] as [$table,$status]){$q=$db->prepare("SELECT COUNT(*) FROM $table WHERE school_id=? AND status=?");$q->execute([$school,$status]);$pending+=(int)$q->fetchColumn();}$q=$db->prepare('SELECT COUNT(*) FROM inventory_items WHERE school_id=? AND reorder_threshold IS NOT NULL AND quantity<=reorder_threshold');$q->execute([$school]);$lowStock=(int)$q->fetchColumn();director_dashboard_json(200,['ok'=>true,'data'=>['active_pupils'=>(int)$pupils['pupils'],'new_pupils_30d'=>(int)$pupils['new_pupils'],'active_staff'=>$staff,'month_net_payments'=>$payments,'outstanding_fees'=>$arrears,'attendance_marked'=>$marked,'attendance_rate'=>$eligible>0?round(((int)$attendance['attended']/$eligible)*100,1):null,'confirmed_lessons_30d'=>$confirmed,'pending_approvals'=>$pending,'low_stock_items'=>$lowStock]]);}catch(Throwable $e){error_log('Director dashboard request failed: '.$e->getMessage());director_dashboard_json(500,['ok'=>false,'message'=>'Director dashboard data could not be loaded.']);}
